def max_sum(arr, n):
    """Write a function to find the maximum sum of bi-tonic sub-sequence for the given array.

    A bitonic subsequence first strictly increases and then strictly
    decreases. A purely increasing or purely decreasing subsequence is
    also allowed, with the peak at an endpoint. Only the first ``n``
    elements of ``arr`` are considered, and an empty input has sum 0.
    """
    if not arr or n <= 0:
        return 0

    values = list(arr)[:n]
    if not values:
        return 0

    size = len(values)

    # increasing[i] is the maximum sum of a strictly increasing
    # subsequence ending exactly at index i.
    increasing = list(values)
    for i in range(size):
        for j in range(i):
            if values[j] < values[i]:
                candidate = increasing[j] + values[i]
                if candidate > increasing[i]:
                    increasing[i] = candidate

    # decreasing[i] is the maximum sum of a strictly decreasing
    # subsequence starting exactly at index i.
    decreasing = list(values)
    for i in range(size - 1, -1, -1):
        for j in range(i + 1, size):
            if values[j] < values[i]:
                candidate = decreasing[j] + values[i]
                if candidate > decreasing[i]:
                    decreasing[i] = candidate

    # Use each element as the peak. It is counted in both sums, so
    # subtract it once when combining the two sides.
    return max(
        increasing[i] + decreasing[i] - values[i] for i in range(size)
    )
